-- Additive CF-03a: D1-only reservation lifecycle. No R2 URL or object is issued.
PRAGMA foreign_keys=ON;
CREATE TABLE workspace_storage_usage(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),used_bytes INTEGER NOT NULL DEFAULT 0 CHECK(used_bytes>=0),reserved_bytes INTEGER NOT NULL DEFAULT 0 CHECK(reserved_bytes>=0));
INSERT INTO workspace_storage_usage(workspace_id) SELECT id FROM workspaces;
CREATE TRIGGER workspace_storage_usage_create AFTER INSERT ON workspaces BEGIN INSERT INTO workspace_storage_usage(workspace_id) VALUES(NEW.id); END;
CREATE TRIGGER workspace_storage_usage_no_delete BEFORE DELETE ON workspace_storage_usage BEGIN SELECT RAISE(ABORT,'IMMUTABLE_STORAGE_LEDGER'); END;

CREATE TABLE upload_sessions(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES users(id),created_by_session_id TEXT NOT NULL,workspace_id TEXT NOT NULL REFERENCES workspaces(id),project_id TEXT NOT NULL,album_id TEXT NOT NULL,storage_node_id TEXT NOT NULL REFERENCES storage_nodes(id),object_key TEXT NOT NULL UNIQUE,original_filename TEXT NOT NULL CHECK(length(original_filename) BETWEEN 1 AND 255),expected_bytes INTEGER NOT NULL CHECK(expected_bytes>0 AND expected_bytes<=9000000000),reserved_bytes INTEGER NOT NULL CHECK(reserved_bytes=expected_bytes),status TEXT NOT NULL CHECK(status IN('reserved','cancelled','expired')),created_at_ms INTEGER NOT NULL,expires_at_ms INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL,created_request_id TEXT NOT NULL,updated_by_request_id TEXT NOT NULL,updated_by_session_id TEXT,updated_by_actor_type TEXT NOT NULL CHECK(updated_by_actor_type IN('user','system')),FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id),FOREIGN KEY(album_id,project_id,workspace_id) REFERENCES albums(id,project_id,workspace_id),CHECK(expires_at_ms=created_at_ms+900000),CHECK(object_key=workspace_id||'/'||project_id||'/'||album_id||'/'||id||'/original'));
CREATE INDEX upload_sessions_expiry ON upload_sessions(status,expires_at_ms);
CREATE INDEX upload_sessions_album ON upload_sessions(album_id,status);

CREATE TABLE storage_reservations(id TEXT PRIMARY KEY REFERENCES upload_sessions(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),storage_node_id TEXT NOT NULL REFERENCES storage_nodes(id),reserved_bytes INTEGER NOT NULL CHECK(reserved_bytes>0),created_at_ms INTEGER NOT NULL,expires_at_ms INTEGER NOT NULL);
CREATE INDEX storage_reservations_workspace ON storage_reservations(workspace_id,expires_at_ms);

CREATE TABLE upload_requests(actor_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('upload.reserved','upload.cancelled')),payload_json TEXT NOT NULL,session_id TEXT NOT NULL,upload_session_id TEXT NOT NULL,workspace_id TEXT,project_id TEXT,album_id TEXT,storage_node_id TEXT,object_key TEXT,original_filename TEXT,expected_bytes INTEGER,created_at_ms INTEGER NOT NULL,result_json TEXT,PRIMARY KEY(actor_id,request_id));
CREATE TRIGGER upload_request_guard BEFORE INSERT ON upload_requests BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM owners o JOIN owner_sessions s ON s.userId=o.user_id WHERE o.user_id=NEW.actor_id AND o.enabled=1 AND s.id=NEW.session_id AND s.expiresAt>unixepoch('subsec')*1000) THEN RAISE(ABORT,'OWNER_REQUIRED') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM request_commands c WHERE c.actor_id=NEW.actor_id AND c.request_id=NEW.request_id) THEN RAISE(ABORT,'REQUEST_ID_CONFLICT') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM upload_requests c WHERE c.actor_id=NEW.actor_id AND c.request_id=NEW.request_id AND (c.operation<>NEW.operation OR c.payload_json<>NEW.payload_json)) THEN RAISE(ABORT,'REQUEST_ID_CONFLICT') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM upload_requests c WHERE c.actor_id=NEW.actor_id AND c.request_id=NEW.request_id) THEN RAISE(IGNORE) END; SELECT CASE WHEN NEW.created_at_ms<unixepoch('subsec')*1000-60000 OR NEW.created_at_ms>unixepoch('subsec')*1000+60000 THEN RAISE(ABORT,'INVALID_TIMESTAMP') END; SELECT CASE WHEN NEW.operation='upload.reserved' AND (NEW.workspace_id IS NULL OR NEW.project_id IS NULL OR NEW.album_id IS NULL OR NEW.storage_node_id<>'primary' OR NEW.object_key<>NEW.workspace_id||'/'||NEW.project_id||'/'||NEW.album_id||'/'||NEW.upload_session_id||'/original' OR NEW.original_filename IS NULL OR NEW.expected_bytes IS NULL OR NEW.expected_bytes<=0 OR NEW.expected_bytes>9000000000) THEN RAISE(ABORT,'INVALID_INPUT') END; SELECT CASE WHEN NEW.operation='upload.reserved' AND NOT EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id AND p.workspace_id=a.workspace_id JOIN workspaces w ON w.id=p.workspace_id JOIN storage_nodes n ON n.id=NEW.storage_node_id AND n.status='active' WHERE a.id=NEW.album_id AND a.project_id=NEW.project_id AND a.workspace_id=NEW.workspace_id AND p.status IN('draft','uploading') AND a.state IN('draft','active') AND w.owner_user_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation='upload.reserved' AND EXISTS(SELECT 1 FROM workspace_storage_usage u JOIN workspaces w ON w.id=u.workspace_id WHERE u.workspace_id=NEW.workspace_id AND u.used_bytes+u.reserved_bytes+NEW.expected_bytes>w.quota_bytes) THEN RAISE(ABORT,'STORAGE_QUOTA_EXCEEDED') END; SELECT CASE WHEN NEW.operation='upload.reserved' AND NOT EXISTS(SELECT 1 FROM workspace_storage_usage u WHERE u.workspace_id=NEW.workspace_id) THEN RAISE(ABORT,'STORAGE_LEDGER_UNAVAILABLE') END; SELECT CASE WHEN NEW.operation='upload.reserved' AND NOT EXISTS(SELECT 1 FROM storage_nodes n WHERE n.id=NEW.storage_node_id AND n.status='active' AND n.used_bytes+n.reserved_bytes+NEW.expected_bytes<=n.quota_bytes) THEN RAISE(ABORT,'STORAGE_QUOTA_EXCEEDED') END; SELECT CASE WHEN NEW.operation='upload.cancelled' AND (NEW.workspace_id IS NOT NULL OR NEW.project_id IS NOT NULL OR NEW.album_id IS NOT NULL OR NEW.storage_node_id IS NOT NULL OR NEW.object_key IS NOT NULL OR NEW.original_filename IS NOT NULL OR NEW.expected_bytes IS NOT NULL) THEN RAISE(ABORT,'INVALID_INPUT') END; SELECT CASE WHEN NEW.operation='upload.cancelled' AND EXISTS(SELECT 1 FROM upload_sessions u WHERE u.id=NEW.upload_session_id AND u.actor_id=NEW.actor_id AND u.status<>'reserved') THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; SELECT CASE WHEN NEW.operation='upload.cancelled' AND EXISTS(SELECT 1 FROM upload_sessions u WHERE u.id=NEW.upload_session_id AND u.actor_id=NEW.actor_id AND u.status='reserved' AND u.expires_at_ms<=NEW.created_at_ms) THEN RAISE(ABORT,'UPLOAD_SESSION_EXPIRED') END; SELECT CASE WHEN NEW.operation='upload.cancelled' AND NOT EXISTS(SELECT 1 FROM upload_sessions u WHERE u.id=NEW.upload_session_id AND u.actor_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; END;

DROP TRIGGER request_command_guard;
CREATE TRIGGER request_command_guard BEFORE INSERT ON request_commands BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM owners o JOIN owner_sessions s ON s.userId=o.user_id WHERE o.user_id=NEW.actor_id AND o.enabled=1 AND s.id=NEW.session_id AND s.expiresAt>unixepoch('subsec')*1000) THEN RAISE(ABORT,'OWNER_REQUIRED') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM upload_requests u WHERE u.actor_id=NEW.actor_id AND u.request_id=NEW.request_id) THEN RAISE(ABORT,'REQUEST_ID_CONFLICT') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM request_commands c WHERE c.actor_id=NEW.actor_id AND c.request_id=NEW.request_id AND (c.operation<>NEW.operation OR c.payload_json<>NEW.payload_json)) THEN RAISE(ABORT,'REQUEST_ID_CONFLICT') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM request_commands c WHERE c.actor_id=NEW.actor_id AND c.request_id=NEW.request_id) THEN RAISE(IGNORE) END; SELECT CASE WHEN NEW.operation='workspace.created' AND (SELECT count(*) FROM workspaces WHERE owner_user_id=NEW.actor_id)>=100 THEN RAISE(ABORT,'WORKSPACE_LIMIT_REACHED') END; SELECT CASE WHEN NEW.operation='project.created' AND NOT EXISTS(SELECT 1 FROM workspaces w WHERE w.id=json_extract(NEW.payload_json,'$.workspaceId') AND w.owner_user_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation='album.created' AND NOT EXISTS(SELECT 1 FROM projects p JOIN workspaces w ON w.id=p.workspace_id WHERE p.id=json_extract(NEW.payload_json,'$.projectId') AND w.owner_user_id=NEW.actor_id AND p.status<>'archived') THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation IN('project.renamed','project.archived','project.restored') AND NOT EXISTS(SELECT 1 FROM projects p JOIN workspaces w ON w.id=p.workspace_id WHERE p.id=NEW.resource_id AND w.owner_user_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation IN('album.renamed','album.protection_changed','album.archived','album.restored') AND NOT EXISTS(SELECT 1 FROM albums a JOIN workspaces w ON w.id=a.workspace_id WHERE a.id=NEW.resource_id AND w.owner_user_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation='project.renamed' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND revision=json_extract(NEW.payload_json,'$.expectedRevision') AND status<>'archived') THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status='archived') THEN 'RESOURCE_NOT_EDITABLE' ELSE 'CONCURRENT_MODIFICATION' END) END; SELECT CASE WHEN NEW.operation='album.renamed' AND NOT EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id AND p.workspace_id=a.workspace_id WHERE a.id=NEW.resource_id AND a.revision=json_extract(NEW.payload_json,'$.expectedRevision') AND a.state NOT IN('archived','deleting','deleted') AND p.status<>'archived') THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id AND p.workspace_id=a.workspace_id WHERE a.id=NEW.resource_id AND (a.state IN('archived','deleting','deleted') OR p.status='archived')) THEN 'RESOURCE_NOT_EDITABLE' ELSE 'CONCURRENT_MODIFICATION' END) END; SELECT CASE WHEN NEW.operation='album.protection_changed' AND NOT EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND revision=json_extract(NEW.payload_json,'$.expectedRevision') AND state NOT IN('deleting','deleted')) THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND state IN('deleting','deleted')) THEN 'RESOURCE_NOT_EDITABLE' ELSE 'CONCURRENT_MODIFICATION' END) END; SELECT CASE WHEN NEW.operation='album.protection_changed' AND EXISTS(SELECT 1 FROM albums a WHERE a.id=NEW.resource_id AND ((a.is_pinned=1 AND json_extract(NEW.payload_json,'$.isPinned')=0) OR (a.legal_hold=1 AND json_extract(NEW.payload_json,'$.legalHold')=0)) AND json_extract(NEW.payload_json,'$.confirmUnprotect')<>1) THEN RAISE(ABORT,'PROTECTION_CONFIRMATION_REQUIRED') END; SELECT CASE WHEN NEW.operation IN('project.archived','project.restored') AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND revision=json_extract(NEW.payload_json,'$.expectedRevision')) THEN RAISE(ABORT,'CONCURRENT_MODIFICATION') END; SELECT CASE WHEN NEW.operation='project.archived' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status IN('draft','delivered') AND NOT EXISTS(SELECT 1 FROM albums WHERE project_id=projects.id) AND NOT EXISTS(SELECT 1 FROM photos p WHERE p.project_id=projects.id)) THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status NOT IN('draft','delivered')) THEN 'INVALID_STATE_TRANSITION' ELSE 'CONTENT_NOT_EMPTY_OR_IDLE' END) END; SELECT CASE WHEN NEW.operation='project.restored' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status='archived' AND archived_from_status IS NOT NULL) THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; SELECT CASE WHEN NEW.operation IN('album.archived','album.restored') AND NOT EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id AND p.workspace_id=a.workspace_id WHERE a.id=NEW.resource_id AND a.revision=json_extract(NEW.payload_json,'$.expectedRevision') AND p.status<>'archived') THEN RAISE(ABORT,'CONCURRENT_MODIFICATION') END; SELECT CASE WHEN NEW.operation='album.archived' AND NOT EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND state='draft') THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; SELECT CASE WHEN NEW.operation='album.archived' AND (EXISTS(SELECT 1 FROM photos p WHERE p.album_id=NEW.resource_id) OR NOT EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id WHERE a.id=NEW.resource_id AND p.status IN('draft','delivered'))) THEN RAISE(ABORT,'CONTENT_NOT_EMPTY_OR_IDLE') END; SELECT CASE WHEN NEW.operation='album.restored' AND NOT EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND state='archived' AND archived_from_state='draft') THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; END;
CREATE TRIGGER upload_request_apply_reservation AFTER INSERT ON upload_requests WHEN NEW.operation='upload.reserved' BEGIN INSERT INTO upload_sessions(id,actor_id,created_by_session_id,workspace_id,project_id,album_id,storage_node_id,object_key,original_filename,expected_bytes,reserved_bytes,status,created_at_ms,expires_at_ms,updated_at_ms,created_request_id,updated_by_request_id,updated_by_session_id,updated_by_actor_type) VALUES(NEW.upload_session_id,NEW.actor_id,NEW.session_id,NEW.workspace_id,NEW.project_id,NEW.album_id,NEW.storage_node_id,NEW.object_key,NEW.original_filename,NEW.expected_bytes,NEW.expected_bytes,'reserved',NEW.created_at_ms,NEW.created_at_ms+900000,NEW.created_at_ms,NEW.request_id,NEW.request_id,NEW.session_id,'user'); INSERT INTO storage_reservations(id,workspace_id,storage_node_id,reserved_bytes,created_at_ms,expires_at_ms) VALUES(NEW.upload_session_id,NEW.workspace_id,NEW.storage_node_id,NEW.expected_bytes,NEW.created_at_ms,NEW.created_at_ms+900000); UPDATE workspace_storage_usage SET reserved_bytes=reserved_bytes+NEW.expected_bytes WHERE workspace_id=NEW.workspace_id; UPDATE storage_nodes SET reserved_bytes=reserved_bytes+NEW.expected_bytes WHERE id=NEW.storage_node_id; UPDATE upload_requests SET result_json=(SELECT json_object('id',u.id,'workspaceId',u.workspace_id,'projectId',u.project_id,'albumId',u.album_id,'originalFilename',u.original_filename,'expectedBytes',u.expected_bytes,'reservedBytes',u.reserved_bytes,'status',u.status,'expiresAtMs',u.expires_at_ms,'createdAtMs',u.created_at_ms) FROM upload_sessions u WHERE u.id=NEW.upload_session_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,album_id,action,after_json,request_id) SELECT 'upload:'||u.id,'user',NEW.actor_id,NEW.session_id,u.workspace_id,u.project_id,u.album_id,'upload.reserved',json_object('id',u.id,'workspaceId',u.workspace_id,'projectId',u.project_id,'albumId',u.album_id,'originalFilename',u.original_filename,'expectedBytes',u.expected_bytes,'reservedBytes',u.reserved_bytes,'status',u.status,'expiresAt',strftime('%Y-%m-%dT%H:%M:%fZ',u.expires_at_ms/1000.0,'unixepoch'),'createdAt',strftime('%Y-%m-%dT%H:%M:%fZ',u.created_at_ms/1000.0,'unixepoch')),NEW.request_id FROM upload_sessions u WHERE u.id=NEW.upload_session_id; END;
CREATE TRIGGER upload_request_apply_cancel AFTER INSERT ON upload_requests WHEN NEW.operation='upload.cancelled' BEGIN UPDATE upload_sessions SET status='cancelled',updated_at_ms=NEW.created_at_ms,updated_by_request_id=NEW.request_id,updated_by_session_id=NEW.session_id,updated_by_actor_type='user' WHERE id=NEW.upload_session_id; UPDATE upload_requests SET result_json=(SELECT json_object('id',u.id,'workspaceId',u.workspace_id,'projectId',u.project_id,'albumId',u.album_id,'originalFilename',u.original_filename,'expectedBytes',u.expected_bytes,'reservedBytes',u.reserved_bytes,'status',u.status,'expiresAtMs',u.expires_at_ms,'createdAtMs',u.created_at_ms) FROM upload_sessions u WHERE u.id=NEW.upload_session_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;

CREATE TRIGGER upload_session_transition_guard BEFORE UPDATE ON upload_sessions BEGIN SELECT CASE WHEN NEW.id<>OLD.id OR NEW.actor_id<>OLD.actor_id OR NEW.created_by_session_id<>OLD.created_by_session_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.project_id<>OLD.project_id OR NEW.album_id<>OLD.album_id OR NEW.storage_node_id<>OLD.storage_node_id OR NEW.object_key<>OLD.object_key OR NEW.original_filename<>OLD.original_filename OR NEW.expected_bytes<>OLD.expected_bytes OR NEW.reserved_bytes<>OLD.reserved_bytes OR NEW.created_at_ms<>OLD.created_at_ms OR NEW.expires_at_ms<>OLD.expires_at_ms OR NEW.created_request_id<>OLD.created_request_id THEN RAISE(ABORT,'IMMUTABLE_UPLOAD_SESSION') END; SELECT CASE WHEN OLD.status<>'reserved' OR NEW.status NOT IN('cancelled','expired') THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; SELECT CASE WHEN NEW.status='cancelled' AND NOT EXISTS(SELECT 1 FROM upload_requests r WHERE r.actor_id=OLD.actor_id AND r.request_id=NEW.updated_by_request_id AND r.operation='upload.cancelled' AND r.upload_session_id=OLD.id AND r.session_id=NEW.updated_by_session_id AND NEW.updated_by_actor_type='user' AND NEW.updated_at_ms>=OLD.updated_at_ms) THEN RAISE(ABORT,'OWNER_REQUIRED') END; SELECT CASE WHEN NEW.status='expired' AND NOT (NEW.updated_by_actor_type='system' AND NEW.updated_by_session_id IS NULL AND NEW.updated_by_request_id='reservation-expired:'||OLD.id AND NEW.updated_at_ms>=OLD.expires_at_ms) THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; END;
CREATE TRIGGER upload_session_transition_apply AFTER UPDATE OF status ON upload_sessions BEGIN UPDATE workspace_storage_usage SET reserved_bytes=reserved_bytes-OLD.reserved_bytes WHERE workspace_id=OLD.workspace_id; UPDATE storage_nodes SET reserved_bytes=reserved_bytes-OLD.reserved_bytes WHERE id=OLD.storage_node_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,album_id,action,before_json,after_json,request_id) VALUES('upload-transition:'||NEW.id||':'||NEW.status,NEW.updated_by_actor_type,CASE WHEN NEW.updated_by_actor_type='user' THEN NEW.actor_id ELSE NULL END,NEW.updated_by_session_id,NEW.workspace_id,NEW.project_id,NEW.album_id,'upload.'||NEW.status,json_object('id',OLD.id,'status',OLD.status,'reservedBytes',OLD.reserved_bytes),json_object('id',NEW.id,'status',NEW.status,'reservedBytes',NEW.reserved_bytes),NEW.updated_by_request_id); END;
CREATE TRIGGER upload_sessions_no_delete BEFORE DELETE ON upload_sessions BEGIN SELECT RAISE(ABORT,'IMMUTABLE_UPLOAD_SESSION'); END;
CREATE TRIGGER upload_requests_no_delete BEFORE DELETE ON upload_requests BEGIN SELECT RAISE(ABORT,'IMMUTABLE_UPLOAD_REQUEST'); END;
CREATE TRIGGER upload_requests_no_update BEFORE UPDATE ON upload_requests WHEN OLD.result_json IS NOT NULL OR NEW.actor_id<>OLD.actor_id OR NEW.request_id<>OLD.request_id OR NEW.operation<>OLD.operation OR NEW.payload_json<>OLD.payload_json OR NEW.session_id<>OLD.session_id OR NEW.upload_session_id<>OLD.upload_session_id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.project_id IS NOT OLD.project_id OR NEW.album_id IS NOT OLD.album_id OR NEW.storage_node_id IS NOT OLD.storage_node_id OR NEW.object_key IS NOT OLD.object_key OR NEW.original_filename IS NOT OLD.original_filename OR NEW.expected_bytes IS NOT OLD.expected_bytes OR NEW.created_at_ms<>OLD.created_at_ms OR NEW.result_json IS NULL BEGIN SELECT RAISE(ABORT,'IMMUTABLE_UPLOAD_REQUEST'); END;
CREATE TRIGGER storage_reservations_no_update BEFORE UPDATE ON storage_reservations BEGIN SELECT RAISE(ABORT,'IMMUTABLE_STORAGE_RESERVATION'); END;
CREATE TRIGGER storage_reservations_no_delete BEFORE DELETE ON storage_reservations BEGIN SELECT RAISE(ABORT,'IMMUTABLE_STORAGE_RESERVATION'); END;
CREATE TRIGGER content_archive_upload_guard BEFORE INSERT ON request_commands WHEN NEW.operation IN('project.archived','album.archived') BEGIN SELECT CASE WHEN NEW.operation='project.archived' AND EXISTS(SELECT 1 FROM upload_sessions u WHERE u.project_id=NEW.resource_id AND u.status='reserved') THEN RAISE(ABORT,'UPLOADS_IN_PROGRESS') END; SELECT CASE WHEN NEW.operation='album.archived' AND EXISTS(SELECT 1 FROM upload_sessions u WHERE u.album_id=NEW.resource_id AND u.status='reserved') THEN RAISE(ABORT,'UPLOADS_IN_PROGRESS') END; END;
